from PIL import Image
import sys

def analyze_lsb(image_path):
    try:
        img = Image.open(image_path)
        width, height = img.size
        lsb_image = Image.new("1", (width, height))

        for x in range(width):
            for y in range(height):
                pixel = img.getpixel((x, y))
                red_lsb = pixel[0] & 1
                green_lsb = pixel[1] & 1
                blue_lsb = pixel[2] & 1

                if (red_lsb + green_lsb + blue_lsb) > 1:
                    lsb_image.putpixel((x, y), 1)
                else:
                    lsb_image.putpixel((x, y), 0)

        lsb_output_path = image_path.split(".")[0] + "_lsb.png"
        lsb_image.save(lsb_output_path)

        print(f"LSB analysis image saved at: {lsb_output_path}")
    except Exception as e:
        print(f"Error during LSB processing: {str(e)}")

if __name__ == "__main__":
    input_image = "/home/ctfplayer/ctf_files/short-circuit.jpg"
    analyze_lsb(input_image)

