from PIL import Image

def extract_lsb(image_path):
    image = Image.open(image_path)
    binary_data = ''

    pixels = list(image.getdata())
    for pixel in pixels:
        for color in pixel[:3]:
            binary_data += str(color & 1)

    return binary_data

def binary_to_text(binary):
    text = ''
    for i in range(0, len(binary), 8):
        byte = binary[i:i+8]
        if len(byte) == 8:
            text += chr(int(byte, 2))
    return text

if __name__ == "__main__":
    image_path = "/home/ctfplayer/ctf_files/short-circuit.jpg"
    binary_data = extract_lsb(image_path)
    hidden_message = binary_to_text(binary_data)

    with open("/home/ctfplayer/ctf_files/hidden_message.txt", "w") as f:
        f.write(hidden_message)

    print("Extraction complete. Check hidden_message.txt for the result.")
